# verify both demos with rule: fill entire row with palette[col // W//3], where marker = non-background color
def f(I):
    W=len(I[0])
    bg=collections.Counter(v for r in I for v in r).most_common(1)[0][0]
    p={0:2,1:4,2:3}
    return [[p[c//(W//3)] for c in range(W)] for r in I for c in [r.index(v) for v in set(r) if v!=bg]]
